double quantile(std::vector<double> values, double fraction) {
    if (values.empty()) {
        return 0;
    }
    std::sort(values.begin(), values.end());
    return values[static_cast<size_t>(fraction * (values.size() - 1))];
}

QJsonObject summarizeGrid(const mixxx::BeatsPointer& grid,
        double sampleRate,
        double duration) {
    std::vector<double> times;
    QJsonArray jsonTimes;
    for (auto it = grid->iteratorFrom(mixxx::audio::kStartFramePos);
            (*it).value() < duration * sampleRate;
            ++it) {
        const double time = (*it).value() / sampleRate;
        times.push_back(time);
        jsonTimes.append(time);
    }
    const double meanIndex = (static_cast<double>(times.size()) - 1) * 0.5;
    double meanTime = 0;
    for (double time : times) {
        meanTime += time;
    }
    meanTime /= std::max(size_t(1), times.size());
    double covariance = 0;
    double variance = 0;
    for (size_t i = 0; i < times.size(); ++i) {
        const double index = static_cast<double>(i) - meanIndex;
        covariance += index * (times[i] - meanTime);
        variance += index * index;
    }
    const double period = variance > 0 ? covariance / variance : 0;
    const double origin = meanTime - meanIndex * period;
    QJsonArray windows;
    for (double start = 0; start < duration; start += 16) {
        const double end = std::min(start + 16, duration);
        std::vector<double> bpms;
        std::vector<double> residuals;
        for (size_t i = 0; i < times.size(); ++i) {
            if (times[i] < start || times[i] >= end) {
                continue;
            }
            residuals.push_back(1000 * (times[i] - origin - i * period));
            if (i + 1 < times.size() && times[i + 1] > times[i]) {
                bpms.push_back(60 / (times[i + 1] - times[i]));
            }
        }
        windows.append(QJsonObject{{"start_seconds", start},
                {"end_seconds", end},
                {"beat_count", static_cast<int>(residuals.size())},
                {"bpm_p10", quantile(bpms, 0.1)},
                {"bpm_median", quantile(bpms, 0.5)},
                {"bpm_p90", quantile(bpms, 0.9)},
                {"linear_phase_residual_ms", quantile(residuals, 0.5)}});
    }
    QJsonArray markers;
    for (const auto& marker : grid->getMarkers()) {
        markers.append(QJsonObject{{"time_seconds", marker.position().value() / sampleRate},
                {"beats_until_next_marker", marker.beatsTillNextMarker()}});
    }
    return QJsonObject{{"constant", grid->hasConstantTempo()},
            {"grid_sub_version", grid->getSubVersion()},
            {"beat_times_seconds", jsonTimes},
            {"markers", markers},
            {"linear_fit_bpm", period > 0 ? 60 / period : 0},
            {"linear_fit_origin_seconds", origin},
            {"windows", windows}};
}

QJsonObject summarizeEvidence(const mixxx::BeatGridEvidence::Result& result) {
    QJsonArray scores;
    QJsonArray support;
    QJsonArray fullSupport;
    for (size_t i = 0; i < result.scores.size(); ++i) {
        scores.append(result.scores[i]);
        QJsonArray bands;
        for (const auto& band : result.support[i]) {
            bands.append(QJsonObject{{"precision", band.precision}, {"recall", band.recall}});
        }
        support.append(bands);
        fullSupport.append(QJsonObject{{"precision", result.fullSupport[i].precision},
                {"recall", result.fullSupport[i].recall}});
    }
    QJsonArray boundaries;
    for (double boundary : result.phaseBoundaries) {
        boundaries.append(boundary);
    }
    return QJsonObject{{"scores", scores},
            {"support", support},
            {"full_support", fullSupport},
            {"density", result.density},
            {"unstable_density", result.unstableDensity},
            {"reliable", result.reliable},
            {"phase_changes", result.phaseChanges},
            {"phase_boundaries_seconds", boundaries}};
}

TEST_F(BeatMaterialTest, DISABLED_MeasuresExternalManifest) {
    const auto manifestPath = qEnvironmentVariable("MIXXX_BEAT_MATERIAL_MANIFEST");
    const auto outputPath = qEnvironmentVariable("MIXXX_BEAT_MATERIAL_OUTPUT");
    if (manifestPath.isEmpty() || outputPath.isEmpty()) {
        GTEST_SKIP() << "Set MIXXX_BEAT_MATERIAL_MANIFEST to a JSON array of {id,path} "
                        "and MIXXX_BEAT_MATERIAL_OUTPUT to the JSONL destination";
    }
    QFile manifest(manifestPath);
    ASSERT_TRUE(manifest.open(QIODevice::ReadOnly)) << manifest.errorString().toStdString();
    QJsonParseError parseError;
    const auto document = QJsonDocument::fromJson(manifest.readAll(), &parseError);
    ASSERT_EQ(parseError.error, QJsonParseError::NoError);
    ASSERT_TRUE(document.isArray());
    QFile output(outputPath);
    ASSERT_TRUE(output.open(QIODevice::WriteOnly | QIODevice::Truncate))
            << output.errorString().toStdString();
    const auto ids = qEnvironmentVariable("MIXXX_BEAT_MATERIAL_IDS").split(',', Qt::SkipEmptyParts);
    const auto selectedModes = qEnvironmentVariable("MIXXX_BEAT_MATERIAL_MODES")
                                       .split(',', Qt::SkipEmptyParts);
    constexpr std::array<const char*, 3> modeNames{"auto", "constant", "variable"};
    constexpr std::array<mixxx::BeatGridMode, 3> modes{mixxx::BeatGridMode::Auto,
            mixxx::BeatGridMode::Constant,
            mixxx::BeatGridMode::Variable};
    constexpr SINT kChunkFrames = 8192;
    for (const auto& entry : document.array()) {
        const auto item = entry.toObject();
        const auto id = item.value("id").toString();
        ASSERT_FALSE(id.isEmpty());
        if (!ids.isEmpty() && !ids.contains(id)) {
            continue;
        }
        QString path = item.value("path").toString();
        for (const auto* key : {"container_path", "local", "path"}) {
            if (QFileInfo::exists(item.value(key).toString())) {
                path = item.value(key).toString();
                break;
            }
        }
        auto sourceTrack = Track::newTemporary(path);
        SoundSourceProxy proxy(sourceTrack);
        mixxx::AudioSource::OpenParams openParams;
        openParams.setChannelCount(mixxx::audio::ChannelCount::stereo());
        auto source = proxy.openAudioSource(openParams);
        ASSERT_TRUE(source) << path.toStdString();
        if (source->getSignalInfo().getChannelCount() != mixxx::audio::ChannelCount::stereo()) {
            source = mixxx::AudioSourceStereoProxy::create(source, kChunkFrames);
        }
        const auto rate = source->getSignalInfo().getSampleRate();
        const double duration = source->getDuration();
        std::array<TrackPointer, 3> tracks;
        std::array<std::unique_ptr<AnalyzerBeats>, 3> analyzers;
        BeatDetectionSettings settings(config());
        settings.setBeatPluginId(AnalyzerBeats::defaultPlugin().id());
        settings.setFastAnalysis(false);
        for (size_t mode = 0; mode < modes.size(); ++mode) {
            if (!selectedModes.isEmpty() && !selectedModes.contains(modeNames[mode])) {
                continue;
            }
            settings.setTempoMode(modes[mode]);
            tracks[mode] = Track::newTemporary();
            tracks[mode]->setAudioProperties(mixxx::audio::ChannelCount::stereo(),
                    rate,
                    source->getBitrate(),
                    mixxx::Duration::fromSeconds(duration));
            analyzers[mode] = std::make_unique<AnalyzerBeats>(config(), true);
            ASSERT_TRUE(analyzers[mode]->initialize(AnalyzerTrack(tracks[mode]),
                    rate,
                    mixxx::audio::ChannelCount::stereo(),
                    source->frameLength()));
        }
        mixxx::BeatGridEvidence evidence;
        evidence.initialize(rate);
        mixxx::SampleBuffer samples(kChunkFrames * 2);
        SINT position = source->frameIndexRange().start();
        QElapsedTimer timer;
        timer.start();
        while (position < source->frameIndexRange().end()) {
            const auto range = mixxx::IndexRange::forward(position,
                    std::min(kChunkFrames, source->frameIndexRange().end() - position));
            const auto decoded = source->readSampleFrames(mixxx::WritableSampleFrames(range,
                    mixxx::SampleBuffer::WritableSlice(samples.data(), samples.size())));
            ASSERT_FALSE(decoded.frameIndexRange().empty());
            ASSERT_EQ(decoded.frameIndexRange().start(), position);
            const auto count = decoded.frameLength() * 2;
            for (const auto& analyzer : analyzers) {
                if (analyzer) {
                    ASSERT_TRUE(analyzer->processSamples(decoded.readableData(), count));
                }
            }
            ASSERT_TRUE(evidence.processSamples(decoded.readableData(), count));
            position = decoded.frameIndexRange().end();
        }
        evidence.prepare();
        for (size_t mode = 0; mode < modes.size(); ++mode) {
            if (!analyzers[mode]) {
                continue;
            }
            analyzers[mode]->storeResults(tracks[mode]);
            analyzers[mode]->cleanup();
            const auto grid = tracks[mode]->getBeats();
            ASSERT_TRUE(grid) << id.toStdString() << " " << modeNames[mode];
            QJsonObject result = summarizeGrid(grid, rate, duration);
            result.insert("id", id);
            result.insert("mode", modeNames[mode]);
            result.insert("sample_rate", static_cast<double>(rate));
            result.insert("duration_seconds", duration);
            result.insert("decoded_frames", static_cast<double>(position));
            result.insert("bpm", tracks[mode]->getBpm());
            result.insert("elapsed_ms", static_cast<double>(timer.elapsed()));
            result.insert("evidence", summarizeEvidence(evidence.evaluate(grid, true)));
            const QByteArray json = QJsonDocument(result).toJson(QJsonDocument::Compact) + '\n';
            ASSERT_EQ(output.write(json), json.size());
            ASSERT_TRUE(output.flush());
            std::cout << id.toStdString() << " " << modeNames[mode]
                      << " bpm=" << tracks[mode]->getBpm()
                      << " constant=" << grid->hasConstantTempo() << std::endl;
        }
    }
}

